/**
 * @file Dependency-free browser bundle builder.
 * Concatenates scripts/files.json in order, normalizes line endings, and preserves source JSDoc.
 * Writes dist/hg.js without minification. Run npm run build after editing library sources.
 */



const fs = require('node:fs');
const path = require('node:path');
const scripts = require('./files.json');

const root = path.join(__dirname, '..');
const parts = [`/**
 * @file Complete standalone HG browser distribution, including types, arithmetic, and swizzles.
 * Generated by npm run build; edit the source files identified by the section comments.
 * Load with one ordinary script tag to initialize globalThis.hg. Source JSDoc is retained.
 */`];
for (const script of scripts) {
  const source = fs.readFileSync(path.join(root, script), 'utf8').replace(/\r\n/g, '\n');
  parts.push(`// ---- ${script} ----\n${source.trimEnd()}`);
}
fs.mkdirSync(path.join(root, 'dist'), { recursive: true });
fs.writeFileSync(path.join(root, 'dist/hg.js'), parts.join('\n\n') + '\n');
console.log(`Built dist/hg.js from ${scripts.length} source files`);
